input.source:
sig Person {}
sig Student extends Person {}
abstract sig Shape {}
sig Circle, Square extends Shape {}
TwoStudents: run { some disj a, b: Student | a in Student } for 3 but 1 Student, 0 Int
OneStudent: run { some Student and some Person - Student } for 3 but 1 Student, 0 Int
TwoCircles: run { some disj a, b: Circle | a in Circle } for 3 but 1 Circle, 0 Int
SquaresFill: run { #Square = 2 and some Circle } for 3 but 1 Circle

sig Person {}
sig Student extends Person {}
PlainPerson: run { some p: Person | p not in Student } for 2 but 0 Int
AllStudents: run { Person = Student and some Person } for 2 but 0 Int
ExactParent: run { no Student } for 2 but exactly 2 Person, 0 Int
ExactChild: run { Person = Student } for 3 but exactly 2 Student, 0 Int
ChildFillsParent: run { some disj a, b: Student | a in Student } for 1 but 0 Int
assert StudentsArePeople { Student in Person }
StudentsHold: check StudentsArePeople for 3 but 0 Int

sig A {}
Three: run { some disj x, y, z: A | x in A }
Four: run { some disj w, x, y, z: A | w in A }
Overall: run { some disj w, x, y, z: A | w in A } for 4

abstract sig Color {}
one sig Red, Green, Blue extends Color {}
sig Light { color: one Color }
sig Bulb, Lamp {}
Enum: run { Color = Red + Green + Blue } for 3 but 0 Int
NoOther: run { some c: Color | c not in Red + Green + Blue } for 3 but 0 Int
Merged: run { Red = Green } for 3 but 0 Int
TwoLights: run { some disj a, b: Light | a.color != b.color } for 3 but 0 Int
BulbsAndLamps: run { some Bulb and some Lamp and no Bulb & Lamp } for 1 but 0 Int

abstract sig Animal { eats: set Animal }
sig Cat, Dog extends Animal {}
Partition: run { some Cat and some Dog } for 2 but 0 Int
NoPlain: run { some a: Animal | a not in Cat + Dog } for 3 but 0 Int
ThreeCats: run { some disj a, b, c: Cat | a in Cat } for 2 but 0 Int
ChildScope: run { some disj a, b, c: Cat | a in Cat } for 2 but 3 Cat, 0 Int
EatsDogs: run { all c: Cat | some c.eats & Dog } for 2 but 0 Int
assert Disjoint { no Cat & Dog }
DisjointHolds: check Disjoint for 3 but 0 Int

sig Account { owner: one Person }
abstract sig Person {}
sig Customer extends Person { accounts: set Account }
sig Staff extends Person {}
Consistent: run { some accounts and all c: Customer | all a: c.accounts | a.owner = c } for 2 but 0 Int
assert OwnerTyped { Account.owner in Customer + Staff }
OwnerHolds: check OwnerTyped for 3 but 0 Int
StaffOwns: run { some a: Account | a.owner in Staff } for 2 but 0 Int
assert AccountsOwned { all c: Customer | c.accounts.owner in c }
AccountsFail: check AccountsOwned for 2 but 0 Int

abstract sig Shape {}
abstract sig Polygon extends Shape {}
sig Triangle, Square extends Polygon {}
sig Circle extends Shape {}
Levels: run { some Triangle and some Square and some Circle } for 3 but 0 Int
PolygonOnly: run { some Polygon - Triangle - Square } for 3 but 0 Int
Bounded: run { some disj a, b, c, d: Shape | a in Shape } for 3 but 0 Int
assert Layers { Triangle + Square in Polygon and Polygon + Circle = Shape }
LayersHold: check Layers for 3 but 0 Int
ExactSquares: run { no Triangle and no Circle } for 3 but exactly 2 Square, 0 Int

sig Node { succ: lone Node } { succ != this }
sig Box { items: set Item } { some items }
sig Item {}
SelfLoop: run { some n: Node | n.succ = n } for 2 but 0 Int
Chained: run { some succ } for 2 but 0 Int
EmptyBox: run { some b: Box | no b.items } for 2 but 0 Int
BoxesNeedItems: run { some Box and no Item } for 2 but 0 Int
assert NoLoops { no iden & succ }
NoLoopsHolds: check NoLoops for 3 but 0 Int

sig Node { next: lone Node }
sig Marked in Node {}
sig Red, Blue in Node {}
one sig Head in Node {}
Overlap: run { some Red & Blue } for 2 but 0 Int
MarkedAll: run { Marked = Node and some Node } for 2 but 0 Int
assert MarkedInNode { Marked in Node }
MarkedHolds: check MarkedInNode for 3 but 0 Int
HeadAlone: run { no Node - Head } for 2 but 0 Int
NoHead: run { no Head } for 2 but 0 Int
HeadMarked: run { Head in Marked and Head in Red & Blue } for 2 but 0 Int
